  let aS = 0, iS = 0, cross = 0, dd = [];
  for (let i = 0; i < src.length; i++) {
    const [sX, sY, f, sp, amp] = src[i];
    const d = Math.sqrt((sx2-sX)**2 + (sy2-sY)**2);
    dd[i] = d;
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
  }
  for (let i = 0; i < src.length; i++)
    for (let j = i+1; j < src.length; j++)
      cross += Math.sin(dd[i]*src[i][2] + dd[j]*src[j][2] - t*(src[i][3]+src[j][3])*0.3) * 0.04;
  const n = src.length, act = aS/n, inh = iS/n;
  const bg = (Math.sin(sx2*0.04+sy2*0.025+t*0.8) + Math.sin(sx2*0.03-sy2*0.04+t*1.1))/2 + Math.sin((sx2+sy2)*0.12+t*2.5)*0.2 + Math.sin((sx2-sy2)*0.1-t*2)*0.2 + Math.sin(sx2*0.08+t*1.5)*Math.sin(sy2*0.06-t*1.2)*0.15;
  const dist = Math.sqrt((sx2-cx)**2 + (sy2-cy)**2), ang = Math.atan2(sy2-cy, sx2-cx);
