  const spiral2 = Math.sin(dist*0.08+ang*2-t*2.0)*0.2 + Math.sin(dist*0.03-ang*5+t*0.8)*0.15;
  const cell = Math.tanh((Math.sin(sx2*0.15)*Math.sin(sy2*0.15) + Math.sin((sx2+sy2)*0.1+t)*0.5)*1.5)*0.3;
