  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + spiral2 + cross + cell + micro)*2.0);
  const reaction2 = Math.tanh((act*0.5 + inh*0.8 - bg*0.2 - spiral*0.5 + cross*2)*1.5);
  const blend = reaction*0.65 + reaction2*0.15 + (cell+micro)*0.2, v = blend*0.5+0.5;
  const pal = [[5,12,45],[12,45,85],[18,90,115],[25,150,135],[180,190,70],[220,140,55],[200,80,60],[140,35,55],[70,18,45],[5,12,45]];
